/* M2 standalone interaction prototype. All data comes from demo-data.js and is synthetic. */
(() => {
  const data = window.TESTI_DEMO;
  const navItems = [
    ['dashboard','⌂','看板','概览'],['labs','⌁','标志物与化验','记录与趋势'],['followup','◷','监测节点','节点清单'],
    ['course','▤','治疗经过','周期与医生原话'],['fertility','✳','生育力保存','个人记录'],['notes','✎','感受笔记','含私密记录'],
    ['visit','▣','就诊准备','问题与导出'],['trials','⌕','临床研究','本机快照'],['records','▧','资料库','原件与来源']
  ];
  const state = { profile:data.profiles[0].id, page:'dashboard', pane:false, paneWidth:35, paneState:'empty', font:false, pin:null, range:'全部', zoom:100 };
  const $ = (s, root=document) => root.querySelector(s);
  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const profile = () => data.profiles.find(p => p.id === state.profile);
  const main = $('#main');
  const nav = $('#nav');
  const picker = $('#profile-select');
  const dateFmt = d => { const x=d.split('-'); return `${x[0]}.${x[1]}.${x[2]}`; };
  picker.innerHTML = data.profiles.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.tag)}</option>`).join('');
  picker.value=state.profile;
  nav.innerHTML = `<div class="nav-group"><div class="nav-label">我的记录</div>${navItems.slice(0,7).map(n=>link(n)).join('')}</div><div class="nav-group"><div class="nav-label">查找与资料</div>${navItems.slice(7).map(n=>link(n)).join('')}</div>`;
  function link(n){return `<button class="nav-link" data-nav="${n[0]}" title="${n[2]}"><span class="nav-icon" aria-hidden="true">${n[1]}</span><span>${n[2]}</span></button>`}
  function head(title, desc, actions='') { return `<div class="page-head"><div><div class="eyebrow">TESTIPAL · ${esc(profile().tag)}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}<button class="button plain" data-action="discuss">和 AI 讨论</button></div></div>`; }
  function button(label, action, cls='') { return `<button class="button ${cls}" data-action="${action}">${label}</button>`; }
  function lastLab(key){return profile().labs.filter(x=>x.key===key).sort((a,b)=>a.date.localeCompare(b.date)).at(-1)}
  function spark(key){const xs=profile().labs.filter(x=>x.key===key);if(xs.length<2)return '';const mn=Math.min(...xs.map(x=>x.value)),mx=Math.max(...xs.map(x=>x.value));const pts=xs.map((x,i)=>`${i*100/(xs.length-1)},${24-(mx===mn?12:(x.value-mn)/(mx-mn)*20)}`).join(' ');return `<svg viewBox="0 0 100 26" preserveAspectRatio="none" aria-label="${key}合成记录趋势"><polyline fill="none" stroke="currentColor" stroke-width="2" points="${pts}"/></svg>`}
  function metricTile(k){const x=lastLab(k);if(!x)return `<div class="metric-tile"><div class="metric-top">${k}<span>暂无</span></div><div class="metric-value">—</div></div>`;return `<div class="metric-tile"><div class="metric-top"><span>${x.key}</span><span>${profile().labs.filter(z=>z.key===k).length} 次</span></div><div class="metric-value">${x.value}<span class="metric-unit">${esc(x.unit)}</span></div><div class="metric-date">${dateFmt(x.date)} · ${esc(x.org)}</div><div class="spark">${spark(k)}</div></div>`}
  function dashboard(){const p=profile(), next=p.nodes.find(n=>n.status!=='done');return `${head('把近期记录整理好',`你好，${esc(p.name.split(' ·')[0])}。这里显示的是你已记录的事实；不做病情判断。`,button('＋ 记录一项','add-lab','primary'))}<section class="hero"><div class="eyebrow">复查节奏 · 按个人记录呈现</div><h1>今天先把资料和问题放在一起</h1><p>${esc(p.summary)} 你可以从一条化验、一个复查节点或一个想问医生的问题开始。</p><div class="hero-bottom"><span class="pill green">档案：${esc(p.tag)}</span><span class="pill">${p.labs.length} 条标志物记录</span><span class="pill">${p.questions.length} 个待问问题</span>${next?`<span class="pill rust">下一条记录：${esc(next.name)} · ${dateFmt(next.date)}</span>`:''}</div></section><div class="layout grid-2"><section class="card"><div class="card-head"><div><h2>最近的标志物记录</h2><p>按每项自己的单位与记录呈现，不合并不同单位</p></div><button class="button plain" data-nav="labs">查看全部 →</button></div><div class="metric-grid">${['AFP','β-hCG','LDH'].map(metricTile).join('')}</div><div class="action-row">${button('＋ 录入化验','add-lab','primary')}</div></section><section class="card"><div class="card-head"><div><h2>接下来</h2><p>来自你自己记录的节点</p></div><button class="button plain" data-nav="followup">全部节点 →</button></div><div class="timeline">${p.nodes.slice(0,3).map(n=>`<div class="timeline-row"><span class="timeline-date">${dateFmt(n.date)}</span><span class="timeline-node"></span><div><div class="timeline-title">${esc(n.name)} <span class="pill ${n.status==='done'?'green':''}">${n.status==='done'?'已记录完成':'待记录'}</span></div><div class="timeline-note">${esc(n.quote)}</div></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>就诊前准备</h2><p>保留你的问题，方便复诊时查看</p></div><button class="button plain" data-nav="visit">打开清单 →</button></div><div class="list">${p.questions.slice(0,2).map((q,i)=>`<div class="list-item"><div class="profile-row"><span class="step-number">${i+1}</span><strong>${esc(q)}</strong></div></div>`).join('')}</div><div class="action-row">${button('＋ 添加问题','add-question')}</div></section><section class="card"><div class="card-head"><div><h2>最近一次就诊资料</h2><p>生育力保存记录 · 资料状态</p></div><button class="button plain" data-nav="fertility">查看 →</button></div><div class="stat-row"><span class="stat-number">${esc(p.fertility.status)}</span><span class="stat-label">${p.fertility.date?dateFmt(p.fertility.date):'尚未记录'}</span></div><div class="callout" style="margin-top:12px">状态为个人转录记录，不表示医学建议。需要讨论方案时，请带上资料询问你的医生。</div></section></div>`}
  function labs(){const p=profile(),keys=['AFP','β-hCG','LDH'];return `${head('标志物与化验','记录报告上的数值、单位、方法、机构和日期。各指标独立展示，参考范围不在本原型内判读。',button('＋ 录入化验','add-lab','primary'))}<div class="review-banner">演示数据 · AFP、β-hCG、LDH 数值只用于预览信息结构，不对应真实患者或医学阈值。</div><section class="card"><div class="card-head"><div><h2>标志物趋势</h2><p>每条线按该指标全期 min/max 归一化，不可跨指标比较；时间窗筛点不改变全期纵向范围。</p></div><div class="head-actions"><div class="range-chips">${['近3月','近6月','近12月','全部'].map(r=>`<button class="button range-chip" data-action="range" data-range="${r}" aria-pressed="${state.range===r}">${r}</button>`).join('')}</div><label class="zoom-control">缩放 <input type="range" min="40" max="100" step="10" value="${state.zoom||100}" data-zoom aria-label="趋势时间窗缩放"></label><button class="button" data-action="events">治疗/手术事件：${state.events===false?'隐藏':'显示'}</button></div></div><div class="chart-layout"><div class="card chart-controls"><div class="section-title" style="margin-top:0">显示指标</div><div class="chart-rows">${keys.map((k,i)=>`<label class="check-row"><input type="checkbox" checked data-series="${k}"><span style="color:${['#39715c','#ad5537','#50738a'][i]}" aria-hidden="true">●</span>${k}<span class="subtle">${p.labs.filter(x=>x.key===k).length} 点</span></label>`).join('')}</div><div class="callout" style="margin-top:12px">点选数据点可查看报告的原值、日期和来源。方法、单位或机构不同时应拆为不可直接比较的记录组。</div></div><div><div class="chart-tools"><button class="button" data-action="replay">重播时间轴</button></div><svg class="chart-svg" viewBox="0 0 720 260" role="img" aria-label="AFP、β-hCG、LDH各按自身全期范围显示；不同指标不可比较">${renderChart(p)}</svg><div class="chart-empty" ${p.labs.some(x=>inWindow(x.date,p))?'hidden':''}>此时间窗没有所选指标记录。<button class="button" data-action="range" data-range="全部">扩大到全部</button><button class="button" data-action="add-lab">＋ 录入记录</button></div><div id="chart-point-detail" class="chart-point-detail" role="status" aria-live="polite">${pointDetail(p)}</div><p class="muted-line">图示只表达各项记录的日期与相对变化，不支持跨指标比较，也不表示治疗效果。</p></div></div>${eventLane(p)}</section><section class="card" style="margin-top:15px"><div class="card-head"><div><h2>指标卡 · 按类别</h2><p>固定 194px 高；背面是同一指标的历史走势，隐藏面不参与键盘焦点。</p></div></div><div class="metric-card-grid">${keys.map(k=>metricFlipCard(k)).join('')}</div></section><section class="card" style="margin-top:15px"><div class="card-head"><div><h2>最近报告</h2><p>来源信息随记录保留</p></div>${button('＋ 手工补一条','add-lab')}</div><div class="table-wrap"><table><thead><tr><th>日期</th><th>指标</th><th>记录值</th><th>方法 / 机构</th><th>来源</th><th></th></tr></thead><tbody>${p.labs.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${dateFmt(x.date)}</td><td>${esc(x.key)}</td><td>${x.value} ${esc(x.unit)}</td><td>${esc(x.method)} · ${esc(x.org)}</td><td>${esc(x.source)}</td><td><button class="button plain" data-action="correct" data-id="${x.id}">改这一条</button></td></tr>`).join('')||'<tr><td colspan="6">暂无化验记录</td></tr>'}</tbody></table></div></section>`}
  function metricFlipCard(k){const x=lastLab(k),xs=profile().labs.filter(z=>z.key===k),flipped=!!state.flipped?.[k];return `<article class="metric-flip ${flipped?'is-flipped':''}"><div class="metric-flip-inner"><section class="metric-face metric-front" ${flipped?'inert':''}><div class="metric-top"><strong>${k}</strong><span>${xs.length} 次记录</span></div>${x?`<div class="metric-value">${x.value}<span class="metric-unit">${esc(x.unit)}</span></div><div class="metric-date">${dateFmt(x.date)} · ${esc(x.method)} · ${esc(x.org)}</div><p class="metric-source">来源：${esc(x.source)}</p>`:'<div class="metric-value">—</div><p>暂无记录</p>'}<button class="button plain flip-control" data-action="flip" data-key="${k}" aria-pressed="${flipped}">查看趋势 ↻</button></section><section class="metric-face metric-back" ${flipped?'':'inert'}><div class="metric-top"><strong>${k} · 全期</strong><span>${xs.length} 点</span></div>${xs.length>1?spark(k):xs.length===1?'<div class="empty">仅 1 次记录，暂不连线</div>':'<div class="empty">暂无趋势</div>'}<p class="metric-source">${xs.length?`首末日期：${dateFmt(xs[0].date)} → ${dateFmt(xs.at(-1).date)} · 末值 ${xs.at(-1).value} ${esc(xs.at(-1).unit)}`:'暂无首末日期'}；方法/机构见报告表。</p><button class="button plain flip-control" data-action="flip" data-key="${k}" aria-pressed="${flipped}">返回正面 ↻</button></section></div></article>`}
  function rangeWindow(p){const all=[...p.labs.map(x=>x.date),...p.events.map(x=>x.date)].sort(),fullStart=new Date(all[0]||data.today),end=state.range==='全部'?new Date(all.at(-1)||data.today):new Date(data.today),months={'近3月':3,'近6月':6,'近12月':12},baseStart=state.range==='全部'?fullStart:new Date(data.today);if(state.range!=='全部')baseStart.setMonth(baseStart.getMonth()-months[state.range]);const start=new Date(end-(end-baseStart)*(Number(state.zoom||100)/100));return {start,end}}
  function inWindow(date,p){const w=rangeWindow(p),d=new Date(date);return d>=w.start&&d<=w.end}
  function eventLane(p){const events=p.events.filter(e=>inWindow(e.date,p)),win=rangeWindow(p),span=Math.max(1,win.end-win.start);return `<div class="event-swimlane" ${state.events===false?'hidden':''}><strong>治疗 / 手术事件 · 独立泳道</strong>${events.length?`<div class="event-track">${events.map(e=>{const x=100*(new Date(e.date)-win.start)/span;return `<button class="event-chip ${state.focusEvent===e.id?'selected':''}" style="--event-left:${x}%" data-action="event-focus" data-id="${esc(e.id)}" data-event-id="${esc(e.id)}" aria-pressed="${state.focusEvent===e.id}">◇ ${dateFmt(e.date)} · ${esc(e.label)}</button>`}).join('')}</div>`:'<span class="subtle">此时间窗没有事件；可扩大范围查看。</span>'}</div>`}
  function pointDetail(p){if(!state.pin)return '';const x=p.labs.find(v=>v.id===state.pin);if(!x)return `<div class="callout">该记录在当前档案中不可用。<button class="button plain" data-action="clear-point">收起</button></div>`;if(!inWindow(x.date,p))return `<div class="callout">${esc(x.key)} · ${dateFmt(x.date)} 已不在当前时间窗。<button class="button" data-action="range" data-range="全部">显示全部范围</button><button class="button plain" data-action="clear-point">收起</button></div>`;return `<div class="point-detail-head"><strong>${esc(x.key)} · ${x.value} ${esc(x.unit)}</strong><button class="button plain" data-action="clear-point">收起详情</button></div><div>${dateFmt(x.date)} · ${esc(x.method)} · ${esc(x.org)}</div><div>来源：${esc(x.source)} · 合成演示，原件未登记</div>`}
  function refreshTrend(){const p=profile(),svg=$('.chart-svg');if(!svg)return;svg.innerHTML=renderChart(p);const visible=p.labs.filter(x=>inWindow(x.date,p)).filter(x=>document.querySelector(`[data-series="${x.key}"]`)?.checked!==false);svg.hidden=!visible.length;const empty=$('.chart-empty');if(empty)empty.hidden=!!visible.length;const lane=$('.event-swimlane');if(lane)lane.outerHTML=eventLane(p);main.querySelectorAll('[data-range]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.range===state.range)));const zoom=main.querySelector('[data-zoom]');if(zoom)zoom.value=state.zoom||100;const toggle=main.querySelector('[data-action=events]');if(toggle)toggle.textContent=`治疗/手术事件：${state.events===false?'隐藏':'显示'}`;const detail=$('#chart-point-detail');if(detail)detail.innerHTML=pointDetail(p)}
  function renderChart(p){const colors={AFP:'#39715c','β-hCG':'#ad5537',LDH:'#50738a'},win=rangeWindow(p),span=Math.max(1,win.end-win.start),xDate=d=>60+610*Math.max(0,Math.min(1,(new Date(d)-win.start)/span)),selected=['AFP','β-hCG','LDH'].filter(k=>document.querySelector(`[data-series="${k}"]`)?.checked!==false),shown=p.labs.filter(x=>inWindow(x.date,p));let svg='<path d="M48 20V220H696" fill="none" stroke="#dce4dc"/>';svg+=`<text x="60" y="239" font-size="10" fill="#77847c">${win.start.toISOString().slice(0,10)}</text><text x="670" y="239" text-anchor="end" font-size="10" fill="#77847c">${win.end.toISOString().slice(0,10)}</text>`;if(state.events!==false)for(const e of p.events.filter(e=>inWindow(e.date,p))){const x=xDate(e.date);svg+=`<line class="event-guide ${state.focusEvent===e.id?'selected':''}" data-event-id="${esc(e.id)}" x1="${x}" x2="${x}" y1="26" y2="38" stroke="#ad5537" stroke-dasharray="3 4" opacity=".42"/><path class="event-node ${state.focusEvent===e.id?'selected':''}" data-event-id="${esc(e.id)}" d="M${x} 14 l6 6 -6 6 -6 -6 Z" fill="#ad5537"/>`}for(const key of selected){const all=p.labs.filter(x=>x.key===key).sort((a,b)=>a.date.localeCompare(b.date)),items=shown.filter(x=>x.key===key).sort((a,b)=>a.date.localeCompare(b.date));if(!items.length)continue;const vals=all.map(x=>x.value),mn=Math.min(...vals),mx=Math.max(...vals),coords=items.map(x=>[xDate(x.date),190-(mx===mn?0.5:(x.value-mn)/(mx-mn))*145]);if(items.length>1)svg+=`<path class="chart-line" data-series="${key}" pathLength="1" fill="none" stroke="${colors[key]}" stroke-width="2.5" d="${coords.map((c,i)=>`${i?'L':'M'}${c[0]} ${c[1]}`).join(' ')}"/>`;coords.forEach((c,i)=>svg+=`<circle cx="${c[0]}" cy="${c[1]}" r="${i===items.length-1?5.5:4.5}" fill="${colors[key]}" data-point="${items[i].id}" class="${state.pin===items[i].id?'pinned':''}" style="--point-index:${i}" tabindex="0" aria-label="${key} ${items[i].value} ${items[i].unit} · ${items[i].date} · ${items[i].source}"><title>${key} ${items[i].value} ${items[i].unit} · ${items[i].date} · ${items[i].source}</title></circle>`);if(items.length===1)svg+=`<text x="${Math.min(680,coords[0][0]+8)}" y="${coords[0][1]-7}" font-size="10" fill="#45574d">仅 1 次记录，暂不连线</text>`;const y=23+['AFP','β-hCG','LDH'].indexOf(key)*17;svg+=`<circle cx="510" cy="${y}" r="4" fill="${colors[key]}"/><text x="520" y="${y+4}" font-size="11" fill="#45574d">${key} · 全期 ${mn}–${mx} ${all[0].unit}</text>`;const last=items.at(-1),lastY=coords.at(-1)[1]+(['AFP','β-hCG','LDH'].indexOf(key)-1)*13;svg+=`<text class="last-value" x="688" y="${Math.max(42,Math.min(213,lastY))}" text-anchor="end" font-size="10" fill="${colors[key]}">${last.value} ${esc(last.unit)}</text>`}return svg}
  function followup(){const p=profile();return `${head('监测节点','以医生给出的复查安排为准。这里帮助记录日期、完成情况和原话来源。',button('＋ 登记影像','add-imaging','primary'))}<div class="layout grid-2"><section class="card"><div class="card-head"><div><h2>我的监测清单</h2><p>${p.nodes.length} 项个人记录</p></div></div><div class="list">${p.nodes.map((n,i)=>`<div class="list-item"><div class="profile-row"><span class="step-number">${i+1}</span><div><strong>${esc(n.name)}</strong><p>${dateFmt(n.date)} · ${esc(n.source)}</p><div class="quote">“${esc(n.quote)}”</div></div></div><div>${n.status==='done'?'<span class="pill green">已记录完成</span>':`<button class="button" data-action="complete" data-index="${i}">标记完成</button>`}</div></div>`).join('')}</div></section><section class="card"><h2>影像记录</h2><p class="subtle">报告原文由你登记；本台不解释影像结论。</p><div class="empty">还没有影像记录<br><button class="button" style="margin-top:10px" data-action="add-imaging">＋ 登记影像</button></div></section></div>`}
  function course(){const p=profile();return `${head('治疗经过','照录你收到的方案名称、周期编号和医生原话；不生成治疗建议。',button('＋ 医生原话','add-quote','primary'))}<div class="layout grid-2"><section class="card"><div class="card-head"><div><h2>方案与周期记录</h2><p>没有填写的内容保持空白</p></div></div>${p.events.length?`<div class="event-lane">${p.events.map(e=>`<div>◇ ${dateFmt(e.date)} · ${esc(e.label)} <span class="pill">个人记录</span></div>`).join('')}</div>`:'<div class="empty">尚无治疗周期记录</div>'}<div class="action-row">${button('＋ 记录本周期血象','add-lab')}</div></section><section class="card"><h2>医生原话</h2><p class="subtle">原文与来源信息一起保存。分期、方案照录，不自动解释。</p><div class="quote">${p.facts.map(f=>`${esc(f.label)}：${esc(f.value)}（${esc(f.source)}）`).join('<br>')}</div><div class="action-row">${button('＋ 医生原话','add-quote')}</div></section></div>`}
  function fertility(){const f=profile().fertility;return `${head('生育力保存','仅记录你本人了解和经历的事项，并整理希望询问的问题。此页不提供生育力医学建议。',button('＋ 记录生育力事项','edit-fertility','primary'))}<div class="layout grid-2"><section class="card"><div class="card-head"><div><h2>个人记录</h2><p>状态 · 机构 · 日期 · 个人备注</p></div></div><div class="stat-row"><span class="stat-number">${esc(f.status)}</span><span class="stat-label">${f.date?dateFmt(f.date):'暂无日期'}</span></div><p class="subtle">${esc(f.institution||'尚未登记机构')}</p><div class="callout">${esc(f.note)}</div></section><section class="card"><h2>可以带去就诊的问题</h2><div class="list" style="margin-top:12px">${profile().questions.filter(q=>/生育|保存|精子/.test(q)).map(q=>`<div class="list-item"><strong>${esc(q)}</strong></div>`).join('')||'<div class="empty">暂无相关问题。你可以在「就诊准备」里添加。</div>'}</div><div class="action-row"><button class="button" data-action="add-question">＋ 添加问题</button><button class="button" data-nav="visit">打开就诊准备</button></div></section></div>`}
  function notes(){const p=profile(), priv=p.notes.filter(n=>n.private).length;return `${head('感受笔记','记录这段时间的感受。标记为私密的内容不会进入看板摘要、就诊包导出或 AI 草稿。',button('＋ 记一条','add-note','primary'))}<section class="card"><div class="card-head"><div><h2>笔记列表</h2><p>${p.notes.length} 条中私密 ${priv} 条</p></div></div><div class="list">${p.notes.map((n,i)=>`<div class="list-item"><div><strong>${esc(n.text)}</strong><p>${dateFmt(n.date)} · ${n.private?'私密（仅本页可见）':'普通记录'}</p></div><button class="button plain" data-action="correct-note" data-index="${i}">改这一条</button></div>`).join('')}</div><div class="callout" style="margin-top:13px">导出和 AI 草稿都只包含非私密记录；问题清单若源自私密笔记，也继续按私密处理。</div></section>`}
  function visit(){const p=profile();return `${head('就诊准备','把想问的问题与需要带去的资料放在一起。问题按个人原话保留。',button('导出就诊包','export','primary'))}<div class="layout grid-2"><section class="card"><div class="card-head"><div><h2>问题清单</h2><p>${p.questions.length} 个待讨论问题</p></div>${button('＋ 添加问题','add-question')}</div><div class="list">${p.questions.map((q,i)=>`<div class="list-item"><div class="profile-row"><span class="step-number">${i+1}</span><strong>${esc(q)}</strong></div><button class="button plain" data-action="remove-question" data-index="${i}">移出清单</button></div>`).join('')||'<div class="empty">还没有问题。可以先写下最想问的一件事。</div>'}</div></section><section class="card"><h2>导出内容预览</h2><p class="subtle">只含当前档案、已记录的非私密内容。</p><div class="section-title">近期标志物</div>${p.labs.slice(-3).map(x=>`<div class="list-item"><strong>${esc(x.key)} · ${x.value} ${esc(x.unit)}</strong><span class="subtle">${dateFmt(x.date)}</span></div>`).join('')}<div class="section-title">私密笔记</div><p class="subtle">已排除 ${p.notes.filter(n=>n.private).length} 条</p><div class="action-row">${button('下载 JSON 就诊包','export','primary')}</div></section></div>`}
  function trials(){const s=data.sources;return `${head('临床研究','本机快照索引只用于浏览登记的结构化信息；状态未核实，详情请到官方登记页核对。') }<div class="review-banner">宽词检索快照 ${dateFmt(s.snapshotDate)} · ${s.snapshotCount} 条返回记录；疾病相关性尚未逐条核实，不能作为睾丸癌试验总数。采集通道状态如实保留：${Object.entries(s.channelStates).map(([k,v])=>`${esc(k)} ${esc(v)}`).join('；')}。</div><div class="layout grid-2"><section class="card"><div class="card-head"><div><h2>按关键词查找</h2><p>当前原型只展示本机快照状态，不模拟在线检索</p></div></div><label class="field">关键词<input placeholder="例如：testicular cancer" disabled></label><div class="empty" style="margin-top:12px">在线检索暂未连接<br>快照数据可在资料库查看；不能把通道失败说成“没有研究”。</div></section><section class="card"><h2>数据来源与终态</h2><div class="list" style="margin-top:10px">${Object.entries(s.channelStates).map(([k,v])=>`<div class="list-item"><div><strong>${esc(k)}</strong><p>访问日期：2026-11-14 · 研究登记快照</p></div><span class="pill ${v==='FAILED'?'rust':''}">${esc(v)}</span></div>`).join('')}</div></section></div>`}
  function records(){return `${head('资料库','管理原件线索、来源和核对状态。当前原型不读取用户文件。',button('＋ 登记原件','add-record','primary'))}<section class="card"><div class="card-head"><div><h2>已登记资料</h2><p>合成演示档案 · 无真实病历文件</p></div></div><div class="list">${profile().facts.map(f=>`<div class="list-item"><div><strong>${esc(f.label)}：${esc(f.value)}</strong><p>${dateFmt(f.date)} · ${esc(f.source)} · 状态：演示转录，未做医学审核</p></div><button class="button plain" data-action="source">查看来源</button></div>`).join('')}<div class="list-item"><div><strong>临床研究快照</strong><p>235 条宽词检索返回 · ${dateFmt(data.sources.snapshotDate)} · 非疾病相关性计数</p></div><button class="button plain" data-nav="trials">查看</button></div></div><div class="empty" style="margin-top:13px">本原型不上传文件，不连接 MinerU。原件待登记。</div></section>`}
  function settings(){return `${head('设置','仅展示原型状态；这些控件不会写入数据库或联网。')}<div class="settings-grid"><section class="card"><h2>工作区</h2><p class="subtle">本地资料目录：未选择（演示态）</p><button class="button" disabled>选择资料目录 · 未连接宿主</button></section><section class="card"><h2>字体与显示</h2><p class="subtle">大字只放大字号；跟随系统减少动效。</p><button class="button" data-action="font">${state.font?'恢复标准字号':'切换大字'}</button></section><section class="card"><h2>临床数据库</h2><p class="subtle">快照：235 条 · 2026-11-14 · 部分检索通道 FAILED</p><button class="button" data-nav="trials">查看通道终态</button></section><section class="card"><h2>资料解析</h2><p class="subtle">MinerU 未接入。此页不接收凭据，也不会上传资料。</p><button class="button" disabled>未连接</button></section></div>`}
  function paneHtml(){return `<div class="agent-head"><div><strong>AI 对话</strong><div class="subtle">此处是宿主状态模拟</div></div><button class="icon-button" data-action="hide-agent" aria-label="收起 AI 面板">×</button></div><div class="action-row" role="group" aria-label="面板宽度"><button class="button" data-width="25">窄 25%</button><button class="button" data-width="35">标准 35%</button><button class="button" data-width="45">宽 45%</button></div><div class="agent-content"><div>${state.paneState==='conflict'?`<div class="review-banner">检测到已有草稿（模拟）。保留现有输入；新内容未覆盖、未发送。</div><button class="button" data-action="cancel-conflict">取消带入</button>`:state.paneState==='failed'?`<div class="review-banner">模拟连接失败。工作台记录仍保留。</div><button class="button" data-action="retry-agent">重试</button>`:`<span class="agent-sim">宿主模拟 · 非真实 DSH 会话</span><p>尚未连接 DSH Desktop 原生会话。此原型没有消息、不会创建会话，也不会发送任何内容。</p><button class="button" data-action="conflict">模拟已有草稿冲突</button><button class="button" data-action="fail-agent">模拟加载失败</button>`}</div></div><div class="callout">显示位置：业务区右侧 · 收起不会清除页面草稿</div>`}
  function render(){document.body.classList.toggle('large-text',state.font);const pane=$('.agent-pane'),split=$('#agent-splitter');pane.hidden=!state.pane;split.hidden=!state.pane;pane.style.flexBasis=`${state.paneWidth}%`;split.style.right=`calc(${state.paneWidth}% - 4px)`;split.setAttribute('aria-valuenow',state.paneWidth);pane.innerHTML=state.pane?paneHtml():'';main.innerHTML=state.page==='dashboard'?dashboard():state.page==='labs'?labs():state.page==='followup'?followup():state.page==='course'?course():state.page==='fertility'?fertility():state.page==='notes'?notes():state.page==='visit'?visit():state.page==='trials'?trials():state.page==='records'?records():settings();nav.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===state.page));}
  function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
  function modal(title,body,submitLabel,onSubmit){const root=$('#overlay-root');root.innerHTML=`<div class="overlay" data-action="overlay-close"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭">×</button></div><form id="dialog-form"><div class="dialog-body">${body}</div><div class="dialog-actions"><button type="button" class="button" data-action="close">取消</button><button class="button primary" type="submit">${submitLabel}</button></div></form></section></div>`;root.querySelector('form').addEventListener('submit',e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));root.innerHTML='';render()});root.querySelector('.dialog').addEventListener('click',e=>e.stopPropagation());root.querySelector('[data-action="overlay-close"]').addEventListener('click',e=>{if(e.target===e.currentTarget)root.innerHTML=''});root.querySelector('[data-action="close"]').focus()}
  const field=(name,label,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
  function act(action,el){const p=profile();if(action==='add-lab'||action==='correct'){const old=action==='correct'?p.labs.find(x=>x.id===el.dataset.id):null;modal(old?'更正一条化验记录':'录入化验',`<div class="form-grid">${field('date','检查日期','date',old?.date||data.today)}<label class="field">指标<select name="key"><option>AFP</option><option>β-hCG</option><option>LDH</option></select></label>${field('value','报告上的数值','number',old?.value||'','inputmode="decimal" step="any"')}${field('unit','单位','text',old?.unit||'')}${field('method','检测方法','text',old?.method||'')}<label class="field">机构<select name="org"><option>市立医院检验科</option><option>其他（可稍后补充）</option></select></label>${field('source','来源备注','text',old?.source||'报告原文')}</div><p class="muted-line">手工录入仅保存你输入的内容；更正会新增一条记录，不覆盖旧版。</p>`,old?'保存更正':'保存记录',f=>{p.labs.push({id:`${p.id}-new-${Date.now()}`,key:f.get('key'),value:Number(f.get('value')),unit:f.get('unit'),date:f.get('date'),method:f.get('method'),org:f.get('org'),source:f.get('source')});toast('记录已加入本次原型会话（刷新后复原）')} );return}
    if(action==='add-question'){modal('添加一个就诊问题',field('question','你想问医生什么？','text','','placeholder="写下你的原话"'), '加入清单',f=>{p.questions.push(f.get('question'));toast('已加入问题清单')});return}
    if(action==='add-note'){modal('记一条感受',`<div class="form-grid"><label class="field full">你的记录<textarea name="text" required></textarea></label><label><input type="checkbox" name="private" checked> 标记为私密（默认）</label></div>`,'保存笔记',f=>{p.notes.push({text:f.get('text'),private:f.get('private')==='on',date:data.today});toast('已保存；私密内容不会进入导出或 AI 草稿')});return}
    if(action==='add-imaging'){modal('登记影像检查',`<div class="form-grid">${field('date','检查日期','date',data.today)}${field('type','检查名称','text','','placeholder="照录报告名称"')}<label class="field full">报告原文或备注<textarea name="note"></textarea></label></div><p class="muted-line">不在这里解释影像内容。</p>`,'保存登记',()=>toast('影像登记已加入原型会话'));return}
    if(action==='add-quote'){modal('记录医生原话',`<div class="form-grid">${field('date','日期','date',data.today)}<label class="field">分类<select><option>方案</option><option>分期（照录）</option><option>复查安排</option></select></label><label class="field full">原话<textarea required placeholder="尽量照录原文"></textarea></label>${field('source','来源','text','','placeholder="门诊记录/报告等"')}</div>`,'保存原话',()=>toast('原话已加入原型会话'));return}
    if(action==='edit-fertility'){modal('记录生育力事项',`<div class="form-grid"><label class="field">当前状态<select name="status"><option>未记录</option><option>已咨询</option><option>已保存</option><option>暂缓</option><option>未进行</option></select></label>${field('date','日期','date',data.today)}${field('institution','机构','text',p.fertility.institution)}<label class="field full">个人备注<textarea name="note">${esc(p.fertility.note)}</textarea></label></div><p class="muted-line">只记个人过程，不据此生成医学建议。</p>`,'保存记录',f=>{p.fertility.status=f.get('status');p.fertility.date=f.get('date');p.fertility.institution=f.get('institution');p.fertility.note=f.get('note');toast('生育力事项已更新')});return}
    if(action==='complete'){const n=p.nodes[Number(el.dataset.index)];n.status='done';toast('节点完成状态已记录');render();return}
    if(action==='remove-question'){p.questions.splice(Number(el.dataset.index),1);toast('问题已移出清单');render();return}
    if(action==='export'){const packet={synthetic:true,profile:p.name,exportedAt:data.today,questions:p.questions,labs:p.labs.map(({key,value,unit,date,source})=>({key,value,unit,date,source})),notes:p.notes.filter(n=>!n.private),privateNotesExcluded:p.notes.filter(n=>n.private).length};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}));a.download='testipal-visit-pack-demo.json';a.click();URL.revokeObjectURL(a.href);toast(`已导出 JSON；排除私密记录 ${packet.privateNotesExcluded} 条`);return}
    if(action==='agent'||action==='discuss'||action==='discuss-primer'){state.pane=!state.pane;render();toast(state.pane?'宿主模拟：未连接 DSH 会话，未发送任何内容':'已收起；草稿状态保留');return}
    if(action==='hide-agent'){state.pane=false;render();return}
    if(action==='conflict'){state.paneState='conflict';render();return}
    if(action==='cancel-conflict'){state.paneState='empty';toast('已取消带入；现有草稿保留');render();return}
    if(action==='fail-agent'){state.paneState='failed';render();return}
    if(action==='retry-agent'){state.paneState='empty';toast('宿主模拟仍未连接');render();return}
    if(action==='settings'){state.page='settings';render();return}
    if(action==='font'){state.font=!state.font;render();return}
    if(action==='close'){ $('#overlay-root').innerHTML='';return }
    if(action==='range'){state.range=el.dataset.range||'全部';refreshTrend();return}
    if(action==='events'){state.events=state.events===false;refreshTrend();return}
    if(action==='replay'){const svg=$('.chart-svg');if(svg){svg.classList.remove('chart-replay');void svg.getBoundingClientRect().width;svg.classList.add('chart-replay');setTimeout(()=>svg.classList.remove('chart-replay'),1200)}return}
    if(action==='clear-point'){state.pin=null;refreshTrend();return}
    if(action==='event-focus'){state.focusEvent=el.dataset.id;main.querySelectorAll('[data-event-id]').forEach(x=>{x.classList.toggle('selected',x.dataset.eventId===state.focusEvent);if(x.tagName==='BUTTON')x.setAttribute('aria-pressed',String(x.dataset.eventId===state.focusEvent))});return}
    if(action==='flip'){const key=el.dataset.key,now=!(state.flipped?.[key]);state.flipped={...(state.flipped||{}),[key]:now};const card=el.closest('.metric-flip');if(card){card.classList.toggle('is-flipped',now);card.querySelector('.metric-front').inert=now;card.querySelector('.metric-back').inert=!now;card.querySelectorAll('[data-action=flip]').forEach(b=>b.setAttribute('aria-pressed',String(now)))}return}
    if(action==='source'){toast('演示来源，无真实文件');return}
    if(action==='correct-note'){toast('更正笔记：新增修订流程待原型确认');return}
    if(action==='add-record'){toast('原件登记将在下一版展示；当前不读取文件');return}
  }
  function go(page){state.page=page;if(page==='primer')history.pushState({page},'',`#page=primer`);else history.pushState({page},'',`#page=${page}`);render();main.focus({preventScroll:true});window.scrollTo(0,0)}
  document.addEventListener('input',e=>{if(e.target.matches('[data-zoom]')){state.zoom=Number(e.target.value);refreshTrend()}});
  document.addEventListener('change',e=>{if(e.target.matches('[data-series]'))refreshTrend()});
  document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){e.preventDefault();go(n.dataset.nav);return}const b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b)});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-width]');if(b){state.paneWidth=Number(b.dataset.width);render();return}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay-root').innerHTML){$('#overlay-root').innerHTML='';return}if(e.key==='Escape'&&state.pane){state.pane=false;render()}});
  picker.addEventListener('change',()=>{state.profile=picker.value;render();toast('已切换演示档案；整页内容同步更新')});
  const splitter=$('#agent-splitter');let dragStart=null;splitter.addEventListener('pointerdown',e=>{dragStart={x:e.clientX,w:state.paneWidth};splitter.setPointerCapture(e.pointerId);document.body.style.userSelect='none'});splitter.addEventListener('pointermove',e=>{if(!dragStart)return;const frameWidth=$('.frame').getBoundingClientRect().width;state.paneWidth=Math.min(45,Math.max(25,dragStart.w-(e.clientX-dragStart.x)/frameWidth*100));render()});splitter.addEventListener('pointerup',()=>{dragStart=null;document.body.style.userSelect=''});splitter.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();state.paneWidth=e.key==='Home'?25:e.key==='End'?45:Math.min(45,Math.max(25,state.paneWidth+(e.key==='ArrowLeft'?1:-1)));render();splitter.focus()}});
  main.addEventListener('click',e=>{const pt=e.target.closest('[data-point]');if(pt){state.pin=pt.dataset.point;refreshTrend()}});
  main.addEventListener('keydown',e=>{const pt=e.target.closest('[data-point]');if(pt&&(e.key==='Enter'||e.key===' ')){e.preventDefault();state.pin=pt.dataset.point;refreshTrend()}});
  window.addEventListener('popstate',()=>{state.page=location.hash.match(/page=([^&]+)/)?.[1]||'dashboard';render()});
  render();
})();
